-- Draft content for the 'Test lektion' package (barnbyar-1..5). Edit freely.
update public.lessons set description = 'Behov och önskemål – vad pengar är till för och hur du väljer vad de ska räcka till.', estimated_minutes = 10, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Vad är pengar till för?", "title": "Vad är pengar till för?", "body": "<p>Pengar är ett verktyg. De gör det möjligt att byta din tid och ditt arbete mot saker du behöver eller vill ha – mat, kläder, resor, mobil och upplevelser.</p><p>Men pengarna räcker nästan aldrig till allt på en gång. Därför handlar privatekonomi om att <strong>välja</strong>.</p><div class=\"modal-callout\">Att ha koll på sina pengar handlar inte om att ha mycket – utan om att veta vart de tar vägen.</div>"}, {"label": "Steg 2 av 3 – Behov eller önskemål?", "title": "Behov eller önskemål?", "body": "<p>Ett <strong>behov</strong> är något du måste ha för att klara vardagen: mat, ett ställe att bo, kläder efter väder, resor till skolan eller jobbet.</p><p>Ett <strong>önskemål</strong> är något som är kul eller skönt att ha, men som du klarar dig utan: nya sneakers fast de gamla funkar, ännu en streamingtjänst, take away.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Testa själv</div><p><strong>Vinterjacka när du inte har någon</strong> → behov<br><strong>En tredje vinterjacka i ny färg</strong> → önskemål<br><strong>Busskort till skolan</strong> → behov</p></div><p>Önskemål är inte fel! Poängen är att behoven ska vara betalda först.</p>"}, {"label": "Steg 3 av 3 – Var försvinner pengarna?", "title": "Var försvinner pengarna?", "body": "<p>Små köp varje dag märks knappt – men de blir mycket tillsammans.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Räkneexempel</div><p>En energidryck för 25 kr fem dagar i veckan<br>= 125 kr i veckan<br>= ungefär <strong>6 500 kr per år</strong></p></div><p>Tips: skriv upp allt du köper under en vecka. De flesta blir förvånade över vart pengarna tar vägen.</p><div class=\"modal-callout\">Fråga dig före ett köp: Behöver jag det här, eller vill jag bara ha det just nu?</div>"}], "quiz": [{"question": "Vilket av de här är ett behov?", "options": ["En ny mobil fast den gamla fungerar", "Mat för veckan", "En biobiljett", "Ett spel till datorn"], "correct_index": 1, "feedback": "Rätt – mat är något du måste ha för att klara vardagen."}, {"question": "Vad är det smartaste att betala först?", "options": ["Det som är roligast", "Det som är på rea", "Behoven, till exempel mat och resor", "Det dina kompisar köper"], "correct_index": 2, "feedback": "Precis – behoven först, sedan önskemålen."}, {"question": "Ett köp för 30 kr varje dag blir ungefär hur mycket på ett år?", "options": ["Cirka 1 000 kr", "Cirka 3 000 kr", "Cirka 11 000 kr", "Cirka 30 000 kr"], "correct_index": 2, "feedback": "Rätt! 30 kr × 365 dagar ≈ 11 000 kr."}]}'::jsonb where id = 'barnbyar-1';
update public.lessons set description = 'Din första budget – få koll på vad som kommer in och vad som går ut varje månad.', estimated_minutes = 10, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Vad är en budget?", "title": "Vad är en budget?", "body": "<p>En budget är en plan för dina pengar. Du skriver upp vad som kommer <strong>in</strong> (inkomster) och vad som går <strong>ut</strong> (utgifter) under en månad.</p><p>Inkomster kan vara studiebidrag, fickpengar, lön från ett extrajobb eller pengar du får varje månad.</p><div class=\"modal-callout\">En budget bestämmer inte över dig – den hjälper dig att bestämma själv.</div>"}, {"label": "Steg 2 av 3 – Fasta och rörliga utgifter", "title": "Fasta och rörliga utgifter", "body": "<p><strong>Fasta utgifter</strong> är ungefär lika stora varje månad: mobilabonnemang, busskort, streaming.</p><p><strong>Rörliga utgifter</strong> ändras från månad till månad: mat, kläder, nöje, presenter.</p><p>Börja med de fasta – de måste alltid betalas. Det som blir kvar är det du kan planera.</p>"}, {"label": "Steg 3 av 3 – Gör en enkel budget", "title": "Gör en enkel budget", "body": "<p>Så här kan en månad se ut:</p><div class=\"modal-example\"><div class=\"modal-example-label\">Exempel – Sara, 17 år</div><p><strong>In:</strong> studiebidrag 1 250 kr + extrajobb 1 500 kr = <strong>2 750 kr</strong></p><p><strong>Ut:</strong> mobil 200 kr · busskort 450 kr · mat och fika 800 kr · kläder 400 kr · nöje 500 kr = <strong>2 350 kr</strong></p><p><strong>Kvar:</strong> 400 kr – som Sara sparar.</p></div><p>Går budgeten minus? Då behöver du antingen minska en utgift eller öka en inkomst. Börja med de rörliga utgifterna – de är lättast att ändra.</p><div class=\"modal-callout\">Tumregel: pengar in minus pengar ut ska bli noll eller mer.</div>"}], "quiz": [{"question": "Vad visar en budget?", "options": ["Bara vad du har köpt", "Vad som kommer in och vad som går ut", "Hur mycket banken tjänar", "Vad saker kostar i affären"], "correct_index": 1, "feedback": "Rätt – en budget jämför inkomster med utgifter."}, {"question": "Vilken av de här är en fast utgift?", "options": ["Godis", "Mobilabonnemanget", "En present", "Kläder på rea"], "correct_index": 1, "feedback": "Precis – ett abonnemang kostar ungefär lika mycket varje månad."}, {"question": "Din budget går 300 kr minus. Vad är ett bra första steg?", "options": ["Strunta i det", "Låna av en kompis varje månad", "Dra ner på en rörlig utgift, till exempel nöje", "Sluta betala mobilen"], "correct_index": 2, "feedback": "Rätt – rörliga utgifter är lättast att justera."}]}'::jsonb where id = 'barnbyar-2';
update public.lessons set description = 'Spara – varför en buffert är viktig och hur små belopp blir stora.', estimated_minutes = 10, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Varför spara?", "title": "Varför spara?", "body": "<p>Det finns tre bra skäl att spara:</p><p><strong>1. Buffert</strong> – pengar för det oväntade, som en trasig mobil eller en räkning du glömt.<br><strong>2. Mål</strong> – något du vill ha längre fram, som körkort, en resa eller en egen lägenhet.<br><strong>3. Frihet</strong> – sparade pengar ger dig fler val och mindre stress.</p><div class=\"modal-callout\">En buffert gör att en jobbig överraskning inte blir en skuld.</div>"}, {"label": "Steg 2 av 3 – Betala dig själv först", "title": "Betala dig själv först", "body": "<p>Många väntar och sparar det som blir kvar i slutet av månaden – och då är det ofta inget kvar.</p><p>Gör tvärtom: sätt undan sparpengarna <strong>direkt</strong> när du får pengar. Många banker låter dig göra en automatisk överföring till ett sparkonto varje månad.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Exempel</div><p>Du får 2 000 kr. Du flyttar 200 kr till sparkontot samma dag. Resten, 1 800 kr, är det du har att leva på den månaden.</p></div>"}, {"label": "Steg 3 av 3 – Små belopp blir stora", "title": "Små belopp blir stora", "body": "<p>Det spelar mindre roll hur mycket du sparar – det viktiga är att du gör det <strong>regelbundet</strong>.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Räkneexempel</div><p>100 kr i månaden<br>= 1 200 kr på ett år<br>= 6 000 kr på fem år – och mer om pengarna dessutom får ränta.</p></div><p>Sätt ett mål: vad sparar du till, hur mycket behöver du och när vill du ha det? Då blir det lättare att låta bli att ta av pengarna.</p>"}], "quiz": [{"question": "Vad är en buffert?", "options": ["Pengar till nöje", "Pengar för oväntade utgifter", "Ett lån från banken", "En sorts aktie"], "correct_index": 1, "feedback": "Rätt – bufferten är till det oväntade."}, {"question": "Vad betyder ”betala dig själv först”?", "options": ["Köpa något kul först", "Spara direkt när du får pengar", "Betala räkningar sist", "Låna innan du sparar"], "correct_index": 1, "feedback": "Precis – sätt undan sparpengarna innan du börjar handla."}, {"question": "Du sparar 150 kr i månaden. Hur mycket har du efter ett år, utan ränta?", "options": ["150 kr", "1 500 kr", "1 800 kr", "15 000 kr"], "correct_index": 2, "feedback": "Rätt! 150 kr × 12 månader = 1 800 kr."}]}'::jsonb where id = 'barnbyar-3';
update public.lessons set description = 'Betala säkert – kort, Swish och hur du skyddar dig mot bedrägerier.', estimated_minutes = 10, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Olika sätt att betala", "title": "Olika sätt att betala", "body": "<p><strong>Kort</strong> – betalkort kopplat till ditt konto. Pengarna dras direkt.<br><strong>Swish</strong> – du skickar pengar direkt från ditt konto till någon annans, med mobilen.<br><strong>Kontanter</strong> – sedlar och mynt. Bra för att se hur mycket du har kvar.</p><p>Gemensamt för kort och Swish: pengarna är borta direkt. En Swish-betalning går i princip inte att ångra.</p><div class=\"modal-callout\">Swisha bara till personer och företag du känner och litar på.</div>"}, {"label": "Steg 2 av 3 – Så luras bedragare", "title": "Så luras bedragare", "body": "<p>Bedragare försöker få dig att lämna ut koder eller skicka pengar. Vanliga knep:</p><p>• Ett sms eller samtal från ”banken” eller ”polisen” som säger att ditt konto är i fara.<br>• En ”kompis” som har bytt nummer och snabbt behöver låna pengar.<br>• En annons där du kan tjäna mycket pengar snabbt.<br>• Någon som ber dig ta emot pengar på ditt konto och skicka dem vidare – det kallas att vara <strong>penningmålvakt</strong> och är ett brott.</p><div class=\"modal-callout\">Banken eller polisen ringer aldrig och ber dig logga in med BankID eller lämna ut koder.</div>"}, {"label": "Steg 3 av 3 – Skydda dig", "title": "Skydda dig", "body": "<p>• Lämna aldrig ut kortkod, lösenord eller BankID till någon.<br>• Legitimera dig bara med BankID när <strong>du själv</strong> har startat det du gör.<br>• Stressar någon dig? Lägg på och ring själv upp banken på numret på deras webbsida.<br>• Har något hänt? Spärra kortet direkt, kontakta banken och polisanmäl.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Kom ihåg</div><p>Låter det för bra för att vara sant, så är det oftast inte sant.</p></div><p>Det är aldrig pinsamt att bli lurad – prata med en vuxen du litar på så fort som möjligt.</p>"}], "quiz": [{"question": "Någon som säger att den ringer från banken ber dig logga in med BankID. Vad gör du?", "options": ["Loggar in så fort som möjligt", "Lägger på och ringer själv upp banken", "Lämnar ut din kortkod i stället", "Swishar pengarna till ett säkert konto"], "correct_index": 1, "feedback": "Rätt – banken ber dig aldrig om det. Lägg på och ring själv."}, {"question": "Vad är en penningmålvakt?", "options": ["En säkerhetsvakt på banken", "Någon som låter brottslingar använda sitt konto för att flytta pengar", "En app för att spara", "En försäkring"], "correct_index": 1, "feedback": "Precis – och det är ett brott, även om du ”bara hjälper till”."}, {"question": "Vad är sant om Swish?", "options": ["Det är lätt att få tillbaka pengarna", "Pengarna går direkt och är svåra att få tillbaka", "Det fungerar bara med kontanter", "Det är ett lån"], "correct_index": 1, "feedback": "Rätt – därför ska du bara swisha till någon du litar på."}]}'::jsonb where id = 'barnbyar-4';
update public.lessons set description = 'Lån och skulder – vad det kostar att låna och hur du undviker skuldfällan.', estimated_minutes = 10, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Vad är ett lån?", "title": "Vad är ett lån?", "body": "<p>Ett lån är pengar du får använda nu men måste betala tillbaka senare – nästan alltid med <strong>ränta</strong>. Räntan är priset för att låna.</p><p>Det finns också <strong>avgifter</strong>, till exempel uppläggningsavgift och aviavgift. Den <strong>effektiva räntan</strong> visar vad lånet kostar totalt, med avgifterna inräknade.</p><div class=\"modal-callout\">Jämför alltid den effektiva räntan – inte bara den ränta som syns mest i reklamen.</div>"}, {"label": "Steg 2 av 3 – Köp nu, betala sen", "title": "Köp nu, betala sen", "body": "<p>Delbetalning, ”betala senare” och kreditkort gör det lätt att köpa saker du inte har pengar till just nu. Men om du inte betalar i tid kommer påminnelseavgifter och ränta.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Räkneexempel</div><p>Du köper hörlurar för 2 000 kr och delar upp betalningen. Med ränta och avgifter kan du till slut ha betalat 2 400 kr eller mer – för samma hörlurar.</p></div><p>Snabblån och sms-lån har ofta mycket hög effektiv ränta och kan snabbt bli dyra.</p>"}, {"label": "Steg 3 av 3 – Om skulden växer", "title": "Om skulden växer", "body": "<p>Betalar man inte en räkning kommer först en påminnelse, sedan ett inkassokrav. Betalar man fortfarande inte kan skulden hamna hos <strong>Kronofogden</strong>. Då kan man få en <strong>betalningsanmärkning</strong>, som gör det svårare att till exempel hyra en lägenhet eller få ett mobilabonnemang.</p><p>Det bästa du kan göra om du inte kan betala: <strong>hör av dig direkt</strong> till den du är skyldig och be om en betalningsplan, och prata med en vuxen du litar på. Kommunens budget- och skuldrådgivning hjälper också till gratis.</p><div class=\"modal-callout\">Låna bara till det du verkligen behöver – och bara om du vet hur du ska betala tillbaka.</div>"}], "quiz": [{"question": "Vad är ränta?", "options": ["En avgift för att spara", "Priset för att låna pengar", "En sorts skatt", "Pengar du får av staten"], "correct_index": 1, "feedback": "Rätt – räntan är vad det kostar att låna."}, {"question": "Vad visar den effektiva räntan?", "options": ["Bara räntan utan avgifter", "Hela kostnaden för lånet, med avgifter", "Hur mycket du får låna", "Hur snabbt du får pengarna"], "correct_index": 1, "feedback": "Precis – därför är den bäst att jämföra lån med."}, {"question": "Du kan inte betala en räkning i tid. Vad är bäst att göra?", "options": ["Låtsas att den inte finns", "Ta ett sms-lån", "Kontakta den du är skyldig och be om en betalningsplan", "Byta telefonnummer"], "correct_index": 2, "feedback": "Rätt – ju tidigare du hör av dig, desto lättare är det att lösa."}]}'::jsonb where id = 'barnbyar-5';
